import os
import argparse
import random

import numpy as np
import pandas as pd


# ============================================================
# Evaluate balanced pairwise ranking accuracy
#
# 1. Read the MC Dropout mean prediction scores generated by
#      4_calculate_uncertainty.py
#
# 2. Create a class-balanced reference set across
#    Mayo scores M0-M3.
#
# 3. Generate random comparison pairs from the full dataset.
#
# 4. Evaluate pairwise ranking accuracy for:
#      - all different-class pairs
#      - neighboring Mayo scores
#      - M0 vs M1
#      - M1 vs M2
#      - M2 vs M3
#
# 5. Summarize the results across folds using
#    the mean and sample standard deviation.
#
# Output:
# Results/
#   <result_date>/
#     <datatype>_balanced_pair_accuracy.csv
#
# Fold-wise detailed CSV/TXT files can also be saved
# with the --save-details option.
# ============================================================


DEFAULT_DATASET = "LIMUC"
DEFAULT_DATATYPE = "test"
ALL_MODES = ["all", "neighbor", "0_1", "1_2", "2_3"]


def read_pred(root_dir, datatype):
    datafile = os.path.join(root_dir, f"{datatype}_mean_score_and_uncertainty.csv")
    if not os.path.exists(datafile):
        raise FileNotFoundError(f"MC Dropout prediction summary not found: {datafile}")

    data = pd.read_csv(datafile)
    required = {"filename", "label", "mean_score"}
    missing = required - set(data.columns)
    if missing:
        raise ValueError(f"{datafile} is missing required columns: {sorted(missing)}")

    data = data.drop_duplicates("filename").reset_index(drop=True)
    return (
        data["mean_score"].astype(float).to_numpy(),
        data["label"].astype(float).to_numpy(),
        data["filename"].astype(str).to_numpy(),
    )


def count_sample_num(labels):
    sample_num = int(labels.shape[0] / 4)
    diff_num = labels.shape[0] - sample_num * 4
    return sample_num, diff_num


def under_over_sample(array, max_num, array2):
    if len(array) == 0:
        raise RuntimeError("A Mayo class has zero samples; balanced evaluation cannot proceed.")
    if len(array) == max_num:
        return array, array2
    if len(array) < max_num:
        idx = random.choices(range(len(array)), k=max_num - len(array))
        return np.concatenate([array, array[idx]]), np.concatenate([array2, array2[idx]])
    idx = random.sample(range(len(array)), max_num)
    return array[idx], array2[idx]


def make_balanced_reference(scores, labels, filenames):
    sample_num, diff_num = count_sample_num(labels)
    print(f"total_sample:{len(labels)}")
    print(f"each_mayo_sample:{sample_num}")
    random.seed(20191206)

    out_scores, out_labels, out_names = [], [], []
    for mayo in range(4):
        cls_scores = scores[labels == mayo]
        cls_names = filenames[labels == mayo]
        target = sample_num + (1 if diff_num >= mayo + 1 else 0)
        cls_scores, cls_names = under_over_sample(cls_scores, target, cls_names)
        out_scores.append(cls_scores)
        out_labels.append(np.full(len(cls_scores), mayo, dtype=float))
        out_names.append(cls_names)

    return np.concatenate(out_scores), np.concatenate(out_labels), np.concatenate(out_names)


def make_random_pairs(ref_scores, ref_labels, ref_names, pool_scores, pool_labels, pool_names):
    name_to_idx = {name: i for i, name in enumerate(pool_names)}
    pair_table = np.zeros((len(pool_names), len(pool_names)), dtype=bool)
    random.seed(20191125)

    pair_scores, pair_labels, pair_names = [], [], []
    i = 0
    while len(pair_scores) < len(ref_scores):
        lbl = random.choice([0, 1, 2, 3])
        candidates = np.where(pool_labels == lbl)[0]
        if len(candidates) == 0:
            raise RuntimeError(f"No candidate samples for Mayo {lbl}.")
        idx = random.choice(candidates.tolist())

        a_idx = name_to_idx[ref_names[i]]
        b_idx = name_to_idx[pool_names[idx]]
        if not pair_table[a_idx, b_idx]:
            pair_scores.append(pool_scores[idx])
            pair_labels.append(pool_labels[idx])
            pair_names.append(pool_names[idx])
            pair_table[a_idx, b_idx] = True
            pair_table[b_idx, a_idx] = True
            i += 1

    # Keep each generated reference-partner pair intact.
    # Do not shuffle only the partner side after pair construction.
    return (
        np.asarray(pair_scores, float),
        np.asarray(pair_labels, float),
        np.asarray(pair_names, str),
    )


def mode_mask_and_labels(ref_labels, pair_labels, mode):
    diff = ref_labels - pair_labels
    relative = np.full(len(diff), 0.5, dtype=float)
    relative[diff > 0] = 1.0
    relative[diff < 0] = 0.0

    if mode == "all":
        mask = diff != 0
    elif mode == "neighbor":
        mask = np.abs(diff) == 1
    elif mode == "0_1":
        mask = ((ref_labels == 0) & (pair_labels == 1)) | ((ref_labels == 1) & (pair_labels == 0))
    elif mode == "1_2":
        mask = ((ref_labels == 1) & (pair_labels == 2)) | ((ref_labels == 2) & (pair_labels == 1))
    elif mode == "2_3":
        mask = ((ref_labels == 2) & (pair_labels == 3)) | ((ref_labels == 3) & (pair_labels == 2))
    else:
        raise ValueError(f"Unknown mode: {mode}")

    return relative, mask


def evaluate_mode(root_dir, datatype, fold, mode, ref_scores, ref_labels, ref_names, pair_scores, pair_labels, pair_names, save_details=False):
    relative, mask = mode_mask_and_labels(ref_labels, pair_labels, mode)
    score_diff = ref_scores - pair_scores
    judgement = np.ones(len(score_diff), dtype=float)
    judgement[score_diff < 0] = 0.0

    evaluable_num = int(mask.sum())
    if evaluable_num == 0:
        raise RuntimeError(f"No evaluable pairs for mode={mode}, fold={fold}")

    correct_num = int(((judgement == relative) & mask).sum())
    correct_rate = correct_num / evaluable_num

    if save_details:
        legacy_mode = "neighber" if mode == "neighbor" else mode
        txt_path = os.path.join(root_dir, f"{datatype}_balanced_pair_accuracy_{legacy_mode}.txt")
        csv_path = os.path.join(root_dir, f"{datatype}_balanced_pair_accuracy_{legacy_mode}.csv")

        with open(txt_path, "w") as f:
            f.write(f"total_num:\n{len(score_diff)}\n")
            f.write(f"correct_num:\n{correct_num}\n")
            f.write(f"evaluable_num:\n{evaluable_num}\n")
            f.write(f"correct_rate:\n{correct_rate}\n")

        pd.DataFrame({
            "filename": ref_names,
            "pairname": pair_names,
            "mayo": ref_labels,
            "pairmayo": pair_labels,
            "score": ref_scores,
            "pairscore": pair_scores,
            "relative_label": relative,
            "judgement": judgement,
            "evaluate_sample": mask.astype(int),
        }).to_csv(csv_path, index=False)

    print(f"mode={mode} fold={fold} correct={correct_num}/{evaluable_num} rate={correct_rate:.6f}")
    return {"mode": mode, "fold": fold, "correct_rate": correct_rate}


def evaluate_fold(root_dir, datatype, fold, modes, save_details=False):
    pool_scores, pool_labels, pool_names = read_pred(root_dir, datatype)
    ref_scores, ref_labels, ref_names = make_balanced_reference(pool_scores, pool_labels, pool_names)
    pair_scores, pair_labels, pair_names = make_random_pairs(
        ref_scores, ref_labels, ref_names, pool_scores, pool_labels, pool_names
    )
    print(f"pair_number:{len(pair_scores)}")

    return [
        evaluate_mode(
            root_dir, datatype, fold, mode,
            ref_scores, ref_labels, ref_names,
            pair_scores, pair_labels, pair_names,
            save_details=save_details,
        )
        for mode in modes
    ]


def save_summaries(results_root, result_date, dataset, datatype, fold_results, modes):
    result_dir = os.path.join(results_root, result_date)
    os.makedirs(result_dir, exist_ok=True)

    fold_df = pd.DataFrame(fold_results)

    # Wide format: one row per fold, one column per evaluation mode.
    wide_df = (
        fold_df
        .pivot(index="fold", columns="mode", values="correct_rate")
        .reindex(columns=modes)
        .reset_index()
    )

    # Add mean and sample SD as final rows.
    mean_row = {"fold": "mean"}
    std_row = {"fold": "std"}

    for mode in modes:
        values = wide_df[mode].to_numpy(dtype=float)
        mean_row[mode] = round(float(np.mean(values)), 5)
        std_row[mode] = (
            round(float(np.std(values, ddof=1)), 5)
            if len(values) >= 2
            else float("nan")
        )

    output_df = pd.concat(
        [
            wide_df,
            pd.DataFrame([mean_row, std_row]),
        ],
        ignore_index=True,
    )

    output_csv = os.path.join(
        result_dir,
        f"{datatype}_balanced_pair_accuracy.csv",
    )
    output_df.to_csv(output_csv, index=False)

    print("")
    print(f"Result: {result_date}")
    for mode in modes:
        print(
            f"{mode:<8} "
            f"{mean_row[mode]:.5f} ± {std_row[mode]:.5f}"
        )

    print("")
    print("Saved:")
    print(" ", output_csv)


def main():
    parser = argparse.ArgumentParser(
        description="Balanced pair accuracy evaluation using MC Dropout mean_score."
    )
    parser.add_argument(
        "dataset",
        nargs="?",
        default=DEFAULT_DATASET,
    )
    parser.add_argument(
        "result_date",
        help="Result directory containing MC Dropout prediction summaries.",
    )
    parser.add_argument("--folds", default="1,2,3,4,5")
    parser.add_argument("--datatype", default=DEFAULT_DATATYPE)
    parser.add_argument(
        "--mode",
        default="all_modes",
        choices=["all_modes", "all", "neighbor", "neighber", "0_1", "1_2", "2_3"],
    )
    parser.add_argument("--results-root", default="./../Results")
    parser.add_argument(
        "--save-details",
        action="store_true",
        help="Save fold-wise detailed pair CSV/TXT files.",
    )
    args = parser.parse_args()

    folds = [int(v.strip()) for v in args.folds.split(",") if v.strip()]
    if args.mode == "all_modes":
        modes = ALL_MODES
    elif args.mode == "neighber":
        modes = ["neighbor"]
    else:
        modes = [args.mode]

    results = []
    for fold in folds:
        root_dir = os.path.join(args.results_root, args.result_date, f"fold_{fold}")
        results.extend(
            evaluate_fold(
                root_dir,
                args.datatype,
                fold,
                modes,
                save_details=args.save_details,
            )
        )

    save_summaries(
        args.results_root,
        args.result_date,
        args.dataset,
        args.datatype,
        results,
        modes,
    )


if __name__ == "__main__":
    main()
